// Configure stock symbols and crypto pairs
const config = {
  stocks: ['AAPL', 'GOOGL', 'MSFT', 'AMZN', 'TSLA', 'NVDA', 'META'],
  crypto: ['bitcoin', 'ethereum', 'cardano', 'solana', 'polkadot'],
  forex: ['EURUSD', 'GBPUSD', 'USDJPY'],
  alphaVantageKey: process.env.ALPHA_VANTAGE_KEY || 'your-api-key',
  timestamp: new Date().toISOString()
};

return { json: config };

// Process Yahoo Finance stock data
const data = $input.first().json;

if (!data.chart || !data.chart.result || !data.chart.result[0]) {
  return { json: { error: 'Invalid data' } };
}

const result = data.chart.result[0];
const meta = result.meta;
const quote = result.indicators.quote[0];

// Get latest values
const latestIndex = quote.close.length - 1;

const processed = {
  symbol: meta.symbol,
  source: 'yahoo_finance',
  current_price: quote.close[latestIndex],
  open: quote.open[latestIndex],
  high: quote.high[latestIndex],
  low: quote.low[latestIndex],
  volume: quote.volume[latestIndex],
  previous_close: meta.previousClose,
  change: quote.close[latestIndex] - meta.previousClose,
  change_percent: ((quote.close[latestIndex] - meta.previousClose) / meta.previousClose * 100).toFixed(2),
  currency: meta.currency,
  market_state: meta.marketState,
  timestamp: new Date(meta.regularMarketTime * 1000).toISOString(),
  retrieved_at: new Date().toISOString()
};

return { json: processed };

// Process cryptocurrency data from CoinGecko
const data = $input.first().json;

if (!data.market_data) {
  return { json: { error: 'Invalid crypto data' } };
}

const marketData = data.market_data;

const processed = {
  symbol: data.symbol.toUpperCase(),
  name: data.name,
  source: 'coingecko',
  current_price: marketData.current_price.usd,
  market_cap: marketData.market_cap.usd,
  total_volume: marketData.total_volume.usd,
  high_24h: marketData.high_24h.usd,
  low_24h: marketData.low_24h.usd,
  price_change_24h: marketData.price_change_24h,
  price_change_percentage_24h: marketData.price_change_percentage_24h?.toFixed(2),
  price_change_percentage_7d: marketData.price_change_percentage_7d?.toFixed(2),
  price_change_percentage_30d: marketData.price_change_percentage_30d?.toFixed(2),
  market_cap_rank: data.market_cap_rank,
  circulating_supply: marketData.circulating_supply,
  total_supply: marketData.total_supply,
  ath: marketData.ath.usd,
  ath_date: marketData.ath_date.usd,
  atl: marketData.atl.usd,
  atl_date: marketData.atl_date.usd,
  last_updated: data.last_updated,
  retrieved_at: new Date().toISOString()
};

return { json: processed };

// Perform technical analysis and generate insights
const allData = $input.all();

const stocks = allData.filter(item => item.json.source === 'yahoo_finance');
const crypto = allData.filter(item => item.json.source === 'coingecko');

// Calculate market summary
const marketSummary = {
  stocks: {
    total_count: stocks.length,
    gainers: stocks.filter(s => parseFloat(s.json.change_percent) > 0).length,
    losers: stocks.filter(s => parseFloat(s.json.change_percent) < 0).length,
    top_gainer: stocks.reduce((max, s) => 
      parseFloat(s.json.change_percent) > parseFloat(max.json.change_percent) ? s : max
    , stocks[0]),
    top_loser: stocks.reduce((min, s) => 
      parseFloat(s.json.change_percent) < parseFloat(min.json.change_percent) ? s : min
    , stocks[0]),
    avg_change: (stocks.reduce((sum, s) => sum + parseFloat(s.json.change_percent), 0) / stocks.length).toFixed(2)
  },
  crypto: {
    total_count: crypto.length,
    gainers_24h: crypto.filter(c => parseFloat(c.json.price_change_percentage_24h) > 0).length,
    losers_24h: crypto.filter(c => parseFloat(c.json.price_change_percentage_24h) < 0).length,
    top_gainer: crypto.reduce((max, c) => 
      parseFloat(c.json.price_change_percentage_24h) > parseFloat(max.json.price_change_percentage_24h) ? c : max
    , crypto[0]),
    top_loser: crypto.reduce((min, c) => 
      parseFloat(c.json.price_change_percentage_24h) < parseFloat(min.json.price_change_percentage_24h) ? c : min
    , crypto[0]),
    total_market_cap: crypto.reduce((sum, c) => sum + (c.json.market_cap || 0), 0)
  },
  timestamp: new Date().toISOString()
};

// Generate alerts
const alerts = [];

// Stock alerts - significant movements
stocks.forEach(stock => {
  const changePercent = parseFloat(stock.json.change_percent);
  if (Math.abs(changePercent) > 5) {
    alerts.push({
      type: 'stock_movement',
      severity: Math.abs(changePercent) > 10 ? 'high' : 'medium',
      symbol: stock.json.symbol,
      message: `${stock.json.symbol} ${changePercent > 0 ? 'gained' : 'lost'} ${Math.abs(changePercent)}% today`,
      current_price: stock.json.current_price,
      change_percent: changePercent
    });
  }
});

// Crypto alerts - significant movements
crypto.forEach(coin => {
  const changePercent = parseFloat(coin.json.price_change_percentage_24h);
  if (Math.abs(changePercent) > 10) {
    alerts.push({
      type: 'crypto_movement',
      severity: Math.abs(changePercent) > 20 ? 'high' : 'medium',
      symbol: coin.json.symbol,
      name: coin.json.name,
      message: `${coin.json.name} ${changePercent > 0 ? 'surged' : 'dropped'} ${Math.abs(changePercent).toFixed(2)}% in 24h`,
      current_price: coin.json.current_price,
      change_percent: changePercent
    });
  }
});

return {
  json: {
    summary: marketSummary,
    alerts: alerts,
    stocks: stocks.map(s => s.json),
    crypto: crypto.map(c => c.json),
    report_generated_at: new Date().toISOString()
  }
};
